    24→export class DatabaseStorage implements IStorage {
    25→  async getProducts(category?: string): Promise<Product[]> {
    26→    if (category) {
    27→      return await db.select().from(products).where(ilike(products.category, category));
    28→    }
    29→    return await db.select().from(products);
    30→  }
    31→
    32→  async getProduct(id: number): Promise<Product | undefined> {
    33→    const [product] = await db.select().from(products).where(eq(products.id, id));
    34→    return product;
    35→  }
    36→
    37→  async createProduct(insertProduct: InsertProduct): Promise<Product> {
    38→    const [product] = await db.insert(products).values(insertProduct).returning();
    39→    return product;
    40→  }
    41→
    42→  async updateProduct(id: number, update: Partial<InsertProduct>): Promise<Product> {
    43→    const [product] = await db.update(products).set(update).where(eq(products.id, id)).returning();
    44→    return product;
    45→  }
    46→
    47→  async createInquiry(insertInquiry: InsertInquiry): Promise<Inquiry> {
    48→    const [inquiry] = await db.insert(inquiries).values(insertInquiry).returning();
    49→    return inquiry;
    50→  }
    51→
    52→  async getServices(): Promise<Service[]> {
    53→    return await db.select().from(services);
    54→  }
    55→
    56→  async createService(service: InsertService): Promise<Service> {
    57→    const [newService] = await db.insert(services).values(service).returning();
    58→    return newService;
    59→  }
    60→
    61→  async deleteService(id: number): Promise<void> {
    62→    await db.delete(services).where(eq(services.id, id));
    63→  }
    64→
    65→  async getOrders(): Promise<Order[]> {
    66→    return await db.select().from(orders).orderBy(sql`${orders.id} DESC`);
    67→  }
    68→
    69→  async getOrderItems(orderId: number): Promise<OrderItem[]> {
    70→    return await db.select().from(orderItems).where(eq(orderItems.orderId, orderId));
    71→  }
    72→
    73→  async createOrder(order: InsertOrder, items: InsertOrderItem[]): Promise<Order> {
    74→    const [newOrder] = await db.insert(orders).values(order).returning();
    75→    const itemsWithId = items.map(item => ({ ...item, orderId: newOrder.id }));
    76→    await db.insert(orderItems).values(itemsWithId);
    77→    return newOrder;
    78→  }
    79→
    80→  async updateOrderStatus(id: number, status: string): Promise<Order> {
    81→    const [order] = await db.update(orders).set({ status }).where(eq(orders.id, id)).returning();
    82→    return order;
    83→  }
    84→
    85→  async getDailySales(): Promise<{ date: string; total: string; count: number }[]> {
